mapper.select:
select t.entrustId, t.validStatus, t.totleTradeId, t.portfolioId, pp.PORTFOLIO_NAME portfolioName, t.ps, t.targetId, t.exerciseType, t.term, t.contractType, t.amount, t.tradeDate, t.vdate, t.mdate, t.remark, t.workflowId, t.workflowStatus, t.createUser, t.createTime, t.updateUser, t.updateTime from(select wa.ENTRUST_ID entrustId, #{VALID_STATUS_01} validStatus, w.TOTLE_TRADE_ID totleTradeId, w.PORTFOLIO_ID portfolioId, w.PS ps, wa.TARGET_ID targetId, wa.EXERCISE_TYPE exerciseType, wa.TERM term, null holdPurpose, wa.CONTRACT_TYPE contractType, w.SHARE_AMT amount, w.TRADE_DATE tradeDate, w.VDATE vdate, w.MDATE mdate, w.REMARK, w.WORKFLOW_ID workflowId, w.WORKFLOW_STATUS workflowStatus, w.CREATE_USER createUser, w.CREATE_TIME createTime, w.UPDATE_USER updateUser, w.UPDATE_TIME updateTime from WFL_TRD_FIN_PRODUCT_DEAL_TOTAL w left join WFL_TRD_DEAL_TOTAL_ADD wa on w.TOTLE_TRADE_ID = wa.TOTLE_TRADE_ID where (w.ps = #{PS_T01} or w.ps = #{PS_T02}) and w.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F35} and w.TRADE_STATUS = #{TRADE_STATUS_01} and (w.IS_CANCEL is null or w.IS_CANCEL = #{YES_NO_NO})
union all
select ta.ENTRUST_ID entrustId, case when t.IS_CANCEL = #{YES_NO_YES} then #{VALID_STATUS_03} else #{VALID_STATUS_02} end validStatus, t.TOTLE_TRADE_ID totleTradeId, t.PORTFOLIO_ID portfolioId, ftp.EXC_PS ps, fri.BENCHMARK_ID targetId, fer.EXERCISE_TYPE exerciseType, ftp.TERM term, ftp.HOLD_PURPOSE holdPurpose, FRS.STRUCTURE_TYPE contractType, t.SHARE_AMT amount, t.TRADE_DATE tradeDate, t.VDATE vdate, t.MDATE mdate, t.REMARK, null workflowId, null workflowStatus, t.CREATE_USER createUser, t.CREATE_TIME createTime, t.UPDATE_USER updateUser, t.UPDATE_TIME updateTime from TRD_FIN_PRODUCT_DEAL_TOTAL t left join TRD_DEAL_TOTAL_ADD ta on t.TOTLE_TRADE_ID = ta.TOTLE_TRADE_ID left join FIN_TRADE_PRODUCT ftp on t.TOTLE_TRADE_ID = ftp.FINPROD_ID left join FIN_PRODUCT_TYPE fpt on ftp.FINPROD_ID = fpt.FINPROD_ID left join FIN_RATE_INFO fri on fri.FINPROD_ID = t.TOTLE_TRADE_ID left join FIN_EXERCISE_RULE fer on fer.FINPROD_ID = t.TOTLE_TRADE_ID left join FIN_CASH_INFO TC on TC.FINPROD_ID = t.TOTLE_TRADE_ID and TC.CASH_TYPE_1 = #{CASH_TYPE_1_02} left join FIN_RATE_INFO_STRUCTURE FRS on FRS.CASH_ID = TC.CASH_ID where (t.ps = #{PS_T01} or t.ps = #{PS_T02}) and t.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F35} and t.TRADE_STATUS = #{TRADE_STATUS_01} ) t left join PTL_PORTFOLIO pp on pp.PORTFOLIO_ID = t.portfolioId
t.validStatus = #{validStatus}
and t.entrustId like CONCAT_WS('', #{entrustId}, '%')
and (t.portfolioId like CONCAT_WS('', #{portfolioId}, '%') or pp.PARENT_PORTFOLIO_ID like CONCAT_WS('', #{portfolioId}, '%'))
and t.targetId like CONCAT_WS('', #{targetId}, '%')
and t.ps = #{ps}
and t.contractType = #{contractType}
and t.tradeDate >= STR_TO_DATE(#{tradeDateStart}, '%Y-%m-%d')
and t.tradeDate <= STR_TO_DATE(#{tradeDateEnd}, '%Y-%m-%d')
and t.exerciseType = #{exerciseType}
order by t.tradeDate desc
